export const GLOSSARY_SHARD = Object.freeze({"market-order":{"slug":"market-order","cat":"trading","en":"Market order","contentLocale":"zh-Hans","term":"市价单（Market Order）","aka":["Market order","市价委托"],"short":"市价单是以当前市场上最优可得价格立即成交的订单，优点是成交快、几乎一定成交，缺点是无法控制成交价格。","body":[["下市价单时你只需填写数量或金额，不填价格。系统会立即用",["订单簿","order-book"],"对面最好的挂单与你成交：买入按卖方最低价，卖出按买方最高价。挂单不够时，会继续吃下一档价格，直到成交完毕。"],["市价单一定是吃单（Taker），手续费通常比挂单（Maker）高。",["流动性","liquidity"],"好的主流",["交易对","trading-pair"],"用市价单小额买卖问题不大，但在冷门币或剧烈行情中，市价单可能遇到很大的",["滑点","slippage"],"。"],["很多",["交易所","centralized-exchange"],"为了防止极端成交，会给市价单设置价格保护范围，超出范围的部分不成交或被取消，各平台规则不同。",["止损单","stop-loss"],"触发后通常也是以市价单执行，所以在急跌中实际成交价可能比止损价差不少。"]],"example":"假设 BTC/USDT 卖一价 64,000，订单簿卖方只挂了 0.2 BTC，下一档 64,050 挂了 0.5 BTC。你用市价买入 0.5 BTC：0.2 个成交在 64,000，0.3 个成交在 64,050，总价 12,800 + 19,215 = 32,015 USDT，均价 64,030。再加上 0.1% 吃单费约 32 USDT，总成本约 32,047 USDT。","mistakes":["在流动性差的币上用市价单大额买入，成交均价远高于看到的价格。","以为市价单会按“最新成交价”成交，其实是按订单簿对手方价格成交。","行情急剧波动时频繁市价进出，手续费和滑点叠加侵蚀本金。"],"faq":[{"q":"市价单和限价单哪个好？","a":"市价单保证成交但不保证价格，限价单保证价格但不保证成交。急需成交时用市价单，想控制成本时用限价单。"},{"q":"市价单手续费为什么更高？","a":"市价单会立即消耗订单簿上的流动性，属于吃单方，交易所通常对吃单收取比挂单更高的费率。"}],"title":"什么是市价单？市价单的含义与成交方式","description":"市价单是什么？讲清市价单如何按订单簿对手价立即成交、为什么手续费更高、何时会产生滑点，以及和限价单的区别。","related":[["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。"],["maker-taker-fees","挂单费与吃单费（Maker/Taker Fee）","挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。"],["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"],["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"市价、限价、撤单，分别解决什么问题？"},"coin":null,"tool":null,"cta":true},"arbitrage":{"slug":"arbitrage","cat":"trading","en":"Arbitrage","contentLocale":"zh-Hans","term":"套利（Arbitrage）","aka":["搬砖","跨所套利","arbitrage"],"short":"套利是利用同一资产在不同市场、不同产品或不同时间点之间的价格差，同时低买高卖、尽量不承担方向风险来赚取差价的交易方式。","body":[["币圈常把跨",["交易所","centralized-exchange"],"套利叫“搬砖”：A 交易所便宜就在 A 买，B 交易所贵就在 B 卖。此外还有现货和合约之间的",["期现套利","funding-rate-arbitrage"],"、",["永续合约","perpetual-futures"],"的资金费率套利、同一交易所内多个",["交易对","trading-pair"],"之间的三角套利等。"],["套利看起来稳，实际利润往往很薄，成本却不少：两边的吃单手续费、",["提币费","withdrawal-fee"],"、转账等待时间、",["滑点","slippage"],"，以及资金分散在多个交易所带来的平台风险。价差越大的机会，往往越可能伴随充提暂停、流动性差或者网络拥堵。"],"如今主流币的明显价差大多被程序化交易快速抹平，普通用户手动操作很难抢到。如果要尝试，先把每一项成本算清楚，并提前在两边准备好资金，避免依赖链上转账。"],"example":"假设 A 交易所 BTC 报价 60,000 USDT，B 交易所 60,150 USDT，价差 150 USDT。你在 A 买 1 BTC、在 B 卖 1 BTC，若两边吃单费率都是 0.1%，手续费约 60 + 60.15 = 120.15 USDT，净利润只剩约 30 USDT。如果还要把 BTC 从 A 提到 B，再扣一笔提币费并等待确认，价差可能早已消失。","mistakes":["只看价差，不算两边手续费、提币费和滑点。","看到某个币价差特别大就去搬砖，没注意该交易所已暂停充值或提币。","依赖链上转账完成套利，在等待确认期间承担了价格波动风险。"],"faq":[{"q":"搬砖套利还能赚钱吗？","a":"主流币的跨所价差通常很小且很快消失，扣除成本后利润有限。机会更多出现在流动性差或充提受限的币上，但风险也更高。"},{"q":"套利是无风险的吗？","a":"不是。套利主要回避的是价格方向风险，但仍有执行风险、手续费、交易所风险和转账延迟风险。"}],"title":"什么是套利？币圈搬砖和跨所套利详解","description":"解释加密货币套利和“搬砖”的几种常见形式，用实例说明手续费和提币费如何吃掉价差，以及套利中隐藏的风险。","related":[["funding-rate-arbitrage","资金费率套利（Funding Rate Arbitrage）","资金费率套利是买入现货、同时在永续合约开等量空单，保持方向中性，赚取正资金费率期间空头收到的资金费的策略。"],["bid-ask-spread","买卖价差（Bid-Ask Spread）","买卖价差是订单簿上最高买价与最低卖价之间的差额，代表立即买入再立即卖出所要承担的隐性成本。"],["market-maker","做市商（Market Maker）","做市商是在订单簿上持续同时挂出买单和卖单、为市场提供流动性的交易者或机构，主要通过买卖价差和交易所的挂单返佣获利。"],["withdrawal-fee","提币手续费（Withdrawal fee）","提币手续费是你把加密资产从交易所转出到外部地址时，交易所收取的费用，通常按币种和网络收取固定数量，用于覆盖链上Gas费和平台的处理成本。"]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"perpetual-futures":{"slug":"perpetual-futures","cat":"derivatives","en":"Perpetual futures (perps)","contentLocale":"zh-Hans","term":"永续合约（Perpetual Futures）","aka":["永续","永续期货","perp","perps"],"short":"永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。","body":[["传统期货到期就要结算，永续合约取消了到期日，你可以一直持有仓位，只要保证金足够不被",["强平","liquidation"],"。为了防止合约价格长期偏离现货，",["交易所","centralized-exchange"],"引入",["资金费率","funding-rate"],"：合约价格高于",["指数价格","index-price"],"时，通常是多头付给空头；低于时空头付给多头。"],["资金费率在多空用户之间直接互付，交易所一般不收取。结算周期常见为每 8 小时一次，但部分交易所或",["交易对","trading-pair"],"使用 1、2 或 4 小时，具体以合约说明页面为准。只有在结算时刻持仓的人才会收付这笔费用。"],["永续合约的强平通常以",["标记价格","mark-price"],"判断，而不是最新成交价，以减少插针造成的误强平。BTC、ETH 永续是全球成交量最大的加密衍生品之一，Hyperliquid 等链上永续合约交易所也提供类似产品。"]],"example":"假设 BTC 永续合约价格 60,300 USDT，指数价格 60,000，合约溢价约 0.5%，当期资金费率为 +0.01%，每 8 小时结算一次。你持有价值 10,000 USDT 的多单，每次结算需要支付 10,000 × 0.01% = 1 USDT，一天三次共 3 USDT，持有 30 天约 90 USDT。如果你持有的是空单，则会收到这笔费用。","mistakes":["以为永续合约没有持仓成本，长期持有忽略了累积的资金费。","只看最新价判断离强平多远，忽略强平以标记价格为准。","默认所有交易对都是 8 小时结算，没查看具体合约的结算周期。"],"faq":[{"q":"永续合约可以一直拿着吗？","a":"可以，没有到期日。但需要持续支付或收取资金费，并且保证金不足时会被强平。"},{"q":"永续合约和交割合约哪个好？","a":"各有用途。永续合约流动性通常更好、无需移仓，但有资金费；交割合约没有资金费，价格会包含基差，到期自动结算。"}],"title":"永续合约是什么？没有到期日的合约怎么运作","description":"解释永续合约的工作原理、资金费率如何让合约价格贴近现货、结算周期的差异，以及长期持仓需要注意的成本和强平风险。","related":[["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"],["mark-price","标记价格（Mark Price）","标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"],["futures-contract","期货合约（Futures Contract）","期货合约是约定在未来以特定价格买入或卖出某种资产的标准化协议，在加密货币交易所中通常不交割实物币，而是用保证金结算盈亏。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"现货和合约，买到的不是同一件事"},"coin":null,"tool":"/funding-rates","cta":true},"delivery-futures":{"slug":"delivery-futures","cat":"derivatives","en":"Delivery (quarterly) futures","contentLocale":"zh-Hans","term":"交割合约（Delivery Futures）","aka":["季度合约","定期合约","当周合约","quarterly futures"],"short":"交割合约是有固定到期日的期货合约，例如当周、次周、当季、次季合约，到期时按交割价格自动结算，不需要支付资金费率。","body":[["交割合约到期前可以随时平仓，如果持有到期，",["交易所","centralized-exchange"],"会在交割时刻按交割价格结算所有仓位。加密交易所的交割合约一般是现金结算，交割价格多取到期前一段时间的指数平均价，防止被瞬间操纵，具体算法以交易所说明为准。"],["交割合约价格和现货之间的差叫",["基差","futures-basis"],"。",["牛市","bull-market"],"里季度合约常常高于现货（升水），",["熊市","bear-market"],"可能低于现货（贴水）。随着到期日临近，基差会逐渐收敛到接近零。"],["因为没有",["资金费","funding-rate"],"，交割合约适合想锁定一个固定价差的人，比如",["期现套利","funding-rate-arbitrage"],"，或者矿工、长期持币者提前锁定未来卖出价格。缺点是部分交割合约流动性不如永续，持仓到期后如果还想继续，需要手动移仓。"]],"example":"假设你持有 10 个 ETH，现货价 3,000 USDT，当季交割合约价 3,060。你担心下跌，在季度合约开空 10 ETH。到期时 ETH 跌到 2,700：现货少了 (3,000 − 2,700) × 10 = 3,000 USDT，空单赚了 (3,060 − 2,700) × 10 = 3,600 USDT，合计多出 600 USDT，正好是开仓时的基差，未计手续费。","mistakes":["忘记合约到期日，持仓被自动交割结算后才发现。","把季度合约的升水当作市场对未来价格的准确预测。","用流动性很差的远期合约下大额市价单，滑点很大。"],"faq":[{"q":"交割合约到期后仓位会怎样？","a":"到期时交易所按交割价格自动平仓结算，盈亏计入账户，仓位消失。想继续持有需要在新的合约上重新开仓。"},{"q":"交割合约有资金费吗？","a":"没有。交割合约靠到期结算让价格回归现货，所以不需要资金费率；成本体现在开仓时的基差上。"}],"title":"交割合约是什么？季度合约与永续的区别","description":"解释交割合约（季度合约）的到期结算方式、基差的升水与贴水、与永续合约的区别，以及如何用它锁定价格对冲风险。","related":[["futures-contract","期货合约（Futures Contract）","期货合约是约定在未来以特定价格买入或卖出某种资产的标准化协议，在加密货币交易所中通常不交割实物币，而是用保证金结算盈亏。"],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["futures-basis","基差（Futures Basis）","基差是期货合约价格与现货价格之间的差额，期货高于现货叫升水，低于现货叫贴水，到期时交割合约的基差会收敛到接近零。"],["hedging","对冲（Hedging）","对冲是建立一个与现有持仓方向相反或相关的仓位，用来抵消部分价格波动风险的做法，例如持有现货的同时开合约空单。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"现货和合约，买到的不是同一件事"},"coin":null,"tool":"/topics/derivatives","cta":false},"initial-margin":{"slug":"initial-margin","cat":"derivatives","en":"Initial margin","contentLocale":"zh-Hans","term":"初始保证金（Initial Margin）","aka":["起始保证金","开仓保证金","IM"],"short":"初始保证金是开立一笔杠杆或合约仓位时必须冻结的最低资金，等于仓位价值除以杠杆倍数，杠杆越高，所需初始保证金越少。","body":[["初始保证金率 = 1 ÷ ",["杠杆倍数","leverage"],"。10 倍杠杆对应 10% 的初始保证金率，20 倍对应 5%。开仓时",["交易所","centralized-exchange"],"会从你的可用余额中冻结这部分资金，此外还要预留开仓手续费。"],["初始保证金只决定你能不能开出这个仓位，开仓后决定是否被",["强平","liquidation"],"的是",["维持保证金","maintenance-margin"],"。初始保证金和维持保证金之间的差，就是你的仓位能承受的亏损空间。"],"大多数交易所实行阶梯保证金：仓位越大，最高可用杠杆越低，所需初始保证金率越高。所以同一个币，开小仓可以 50 倍，开大仓可能只允许 10 倍以下，具体看交易所的风险限额表。"],"example":["假设你想开一笔价值 30,000 ",["USDT","usdt"]," 的 SOL 多单。用 10 倍杠杆，初始保证金是 30,000 × 10% = 3,000 USDT；用 25 倍杠杆，只需 30,000 × 4% = 1,200 USDT。两种情况下，SOL 每涨跌 1%，盈亏都是 300 USDT，区别只是冻结的资金和",["强平价","liquidation-price"],"的位置不同：25 倍时浮亏还没到 1,200 USDT 就会触发强平。"],"mistakes":["以为初始保证金越少越划算，忽略它同时缩小了承受亏损的空间。","可用余额刚好等于初始保证金时开仓，没预留手续费和波动空间。","不知道阶梯保证金，大仓位下单时发现杠杆被自动下调。"],"faq":[{"q":"初始保证金和维持保证金有什么区别？","a":"初始保证金是开仓门槛，维持保证金是持仓底线。保证金低于维持保证金要求时仓位会被强平。"},{"q":"初始保证金怎么算？","a":"初始保证金等于仓位价值除以杠杆倍数，例如 20,000 USDT 的仓位用 20 倍杠杆，需要 1,000 USDT。"}],"title":"初始保证金是什么？开仓保证金怎么计算","description":"解释合约交易中初始保证金的含义和计算方式、它与杠杆倍数和维持保证金的关系，以及阶梯保证金对大仓位的影响。","related":[["maintenance-margin","维持保证金（Maintenance Margin）","维持保证金是持有合约仓位所需的最低保证金，当仓位的保证金余额（含未实现盈亏）跌到这个水平时，交易所会触发强制平仓。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"],["isolated-margin","逐仓保证金（Isolated Margin）","逐仓保证金是一种保证金模式，每个仓位只使用单独分配给它的保证金，仓位被强平时最多亏掉这部分，不会动用账户里的其他资金。"],["margin-trading","杠杆交易（Margin Trading）","杠杆交易是用自己的资金作保证金，向交易所借入资金或币来放大买卖规模的交易方式，借款要付利息，亏损到一定程度会被强平。"]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"保证金为什么还没归零，就可能出局？"},"coin":null,"tool":null,"cta":false},"portfolio-margin":{"slug":"portfolio-margin","cat":"derivatives","en":"Portfolio margin","contentLocale":"zh-Hans","term":"组合保证金（Portfolio Margin）","aka":["组合保证金模式","PM","portfolio margin"],"short":"组合保证金是一种按整个投资组合的净风险计算保证金的模式，现货、合约、期权的仓位可以互相抵消风险，对冲良好的组合所需保证金更低。","body":[["普通的逐仓、",["全仓模式","cross-margin"],"基本是逐个仓位计算保证金要求。组合保证金则会对整个账户做压力测试：模拟价格大涨大跌、",["波动率","volatility"],"变化等情景，找出组合在最坏情景下可能亏多少，以此作为保证金要求。"],["对于做期现",["对冲","hedging"],"、期权组合或多空配对的专业交易者，组合保证金可以显著提高资金效率，因为互相对冲的仓位不会被重复计算保证金。很多大型",["交易所","centralized-exchange"],"在",["统一账户","unified-trading-account"],"中提供组合保证金模式，通常有资产门槛或需要单独开通。"],["风险在于：保证金占用低，意味着可以开出更大的总仓位；一旦对冲关系失效，例如",["基差","futures-basis"],"剧烈波动、某个币被下调抵押率，保证金要求可能突然上升。它适合能理解并监控组合风险的进阶用户。"]],"example":"假设你持有 1 BTC 现货，同时开 1 BTC 的永续空单，BTC 价格 60,000 USDT。按普通模式，这张空单用 10 倍杠杆要占用 6,000 USDT 保证金。组合保证金系统模拟 BTC 下跌 15%：现货亏 9,000，空单赚 9,000；上涨 15% 时正好相反。组合的方向风险接近零，所需保证金主要覆盖基差和费用等剩余风险，因此通常远低于 6,000 USDT。","mistakes":["以为组合保证金只是“更高的杠杆”，忽略它按情景压力测试计算风险。","利用节省下的保证金大量加仓，放大了对冲失效时的损失。","没注意抵押资产的折算率会调整，导致可用保证金突然减少。"],"faq":[{"q":"组合保证金适合新手吗？","a":"一般不适合。它主要为做对冲和期权组合的进阶交易者设计，需要理解压力测试和各类资产折算规则，很多交易所也设有开通门槛。"},{"q":"组合保证金和全仓有什么区别？","a":"全仓是所有仓位共用余额，但保证金要求基本按每个仓位相加；组合保证金会考虑仓位之间的对冲关系，按整体组合的净风险计算。"}],"title":"组合保证金是什么？Portfolio Margin 详解","description":"解释组合保证金如何用压力测试按整体净风险计算保证金、为什么对冲组合能节省资金，以及它与全仓模式的区别和风险。","related":[["cross-margin","全仓保证金（Cross Margin）","全仓保证金是一种保证金模式，账户内所有可用余额共同为全部全仓仓位提供保证金，抗波动能力更强，但一旦强平可能亏掉整个账户余额。"],["isolated-margin","逐仓保证金（Isolated Margin）","逐仓保证金是一种保证金模式，每个仓位只使用单独分配给它的保证金，仓位被强平时最多亏掉这部分，不会动用账户里的其他资金。"],["unified-trading-account","统一账户（Unified trading account）","统一账户是交易所把现货、杠杆、合约和期权等交易放在同一个账户中的模式，账户里多种资产可以按折算率共同作为保证金，盈亏可以相互抵消。"],["hedging","对冲（Hedging）","对冲是建立一个与现有持仓方向相反或相关的仓位，用来抵消部分价格波动风险的做法，例如持有现货的同时开合约空单。"]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"全仓：为什么一笔亏损会影响别的仓位？"},"coin":null,"tool":null,"cta":false},"short-squeeze":{"slug":"short-squeeze","cat":"derivatives","en":"Short squeeze","contentLocale":"zh-Hans","term":"轧空（Short Squeeze）","aka":["逼空","空头挤压","short squeeze"],"short":"轧空是指价格上涨迫使大量空头止损或被强平，他们的平仓买单又进一步推高价格，形成连锁反应、价格在短时间内急速拉升的现象。","body":[["空单平仓就是买入。当很多人在同一个币上做空，且止损和",["强平价","liquidation-price"],"集中在某些价位，价格只要涨到第一批强平价，系统的",["强平","liquidation"],"买单就会推动价格冲向下一批，像多米诺骨牌一样连环触发。"],["轧空前常见的迹象包括：",["持仓量","open-interest"],"快速增加、",["资金费率","funding-rate"],"明显为负（空头在付钱）、",["多空比","long-short-ratio"],"显示大户偏空、币的",["流通盘","circulating-supply"],"或合约深度较小。这些条件叠加时，一点利好或一笔大买单就可能引发剧烈上涨。"],"反过来也有多头被挤压的情况，价格急跌引发多单连环强平，币圈常称之为“多杀多”。无论哪种，参与者都应该意识到拥挤的一边最脆弱，用止损和合理杠杆保护自己。"],"example":"假设某个币价格 50 USDT，资金费率为 −0.1%，大量空单的强平价集中在 52 到 55 之间。一笔大额买单把价格推到 52，第一批空单被强平，系统市价买入，价格冲到 54，又触发下一批强平，几分钟内价格涨到 57，涨幅 14%。随后强平买盘消失，价格可能回落，但被强平的空头已经离场。","mistakes":["在资金费率深度为负、持仓量暴增的时候继续加仓做空。","做空小市值币不设止损，以为基本面差就一定会跌。","在轧空的急涨中追高买入，忽略强平买盘耗尽后的回落。"],"faq":[{"q":"轧空和逼空是一个意思吗？","a":"是的，都指空头被迫平仓推动价格急涨的过程。"},{"q":"怎么判断可能发生轧空？","a":"常见信号是持仓量快速上升、资金费率明显为负、空单集中且合约深度较薄。这些只是风险提示，不能保证一定会发生。"}],"title":"轧空是什么意思？加密货币逼空如何发生","description":"解释轧空（逼空、Short Squeeze）的形成机制、空头连环强平如何推高价格，以及资金费率和持仓量中常见的预警信号。","related":[["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"],["short-selling","卖空（Short Selling）","卖空是先借入或通过合约卖出自己并不持有的资产，等价格下跌后再买回归还或平仓，从下跌中赚取差价的交易方式。"],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"],["open-interest","持仓量（Open Interest）","持仓量是某个合约市场中所有尚未平仓的合约总量，每一份多单都对应一份空单，它衡量的是有多少资金仍然留在市场里。"]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"usdc":{"slug":"usdc","cat":"stablecoins","en":"USDC","contentLocale":"zh-Hans","term":"USDC（美元币）","aka":["USDC","USD Coin","美元币"],"short":"USDC 是由 Circle 公司发行、与美元 1:1 挂钩的稳定币，储备主要为现金和短期美国国债，以储备披露较透明著称，在 DeFi 和合规场景中使用广泛。","body":[["Circle 会定期公布 USDC 的储备情况并接受第三方鉴证。USDC 发行在",["以太坊","ethereum"],"、Solana、Base、Arbitrum 等多条链上，Circle 还提供跨链转移协议（CCTP），可以在支持的链之间通过销毁再铸造的方式转移原生 USDC。"],["USDC 并非没有风险。2023 年 3 月硅谷银行倒闭时，Circle 有部分储备存放在该行，USDC 一度跌到 0.9 美元以下，几天后恢复挂钩。这说明储备托管的银行风险也会传导到",["稳定币","stablecoin"],"。"],["在欧盟 ",["MiCA","mica"]," 框架下，稳定币发行方需要获得相应授权，USDC 是较早满足这一要求的主流稳定币之一。与 ",["USDT","usdt"]," 一样，发行方可以冻结涉及违法活动的地址。"]],"example":"假设你在 2023 年 3 月那次事件中持有 10,000 USDC，当价格最低跌到约 0.88 美元时，账面价值约为 8,800 美元。如果你恐慌之下按这个价格卖出，就实际损失约 1,200 美元；而继续持有到价格恢复 1 美元附近，账面损失随之消失。当然，在事件发生时，没人能确定它一定会恢复。","mistakes":["以为 USDC 有储备透明度就完全没有脱锚风险。","把以太坊上的 USDC 和其他链上的桥接版 USDC 当成同一种资产。","在不支持 USDC 某条网络的交易所充值，导致无法到账。"],"faq":[{"q":"USDC 和 USDT 有什么区别？","a":"两者都挂钩美元。USDC 由 Circle 发行，储备披露较详细，在欧盟等合规场景更常见；USDT 由 Tether 发行，交易所交易对和 C2C 市场使用更广。"},{"q":"USDC 可以兑换成美元吗？","a":"符合条件的机构客户可以直接向 Circle 赎回，普通用户一般通过交易所卖出换成法币，具体渠道视所在地而定。"}],"title":"USDC 是什么？Circle 美元稳定币详解","description":"USDC 是什么？了解 Circle 发行的 USDC 储备结构、多链与原生跨链方式、2023 年短暂脱锚的原因，以及与 USDT 的主要区别。","related":[["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["usdt","USDT（泰达币）","USDT（泰达币）是由 Tether 公司发行、设计为与美元 1:1 挂钩的稳定币，也是市值和交易量最大的稳定币之一，大多数交易所的现货和合约都以它计价。"],["depeg","脱锚（Depeg）","脱锚是指稳定币或锚定类资产的市场价格明显偏离它承诺跟随的价值，例如本应等于1美元的稳定币跌到0.95美元或涨到1.03美元。"],["mica","MiCA（欧盟加密资产市场法规）","MiCA是欧盟的《加密资产市场法规》，为加密资产发行方、稳定币和加密资产服务提供商（CASP）建立统一的许可和监管规则，适用于全部成员国。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT是美元吗？为什么买币常见它？"},"coin":{"slug":"usdc","name":"USDC","symbol":"USDC"},"tool":null,"cta":false},"launchpool":{"slug":"launchpool","cat":"exchange-features","en":"Launchpool","contentLocale":"zh-Hans","term":"Launchpool（质押挖新币）","aka":["Launchpool","新币挖矿","质押挖矿"],"short":"Launchpool是交易所推出的新币挖矿活动：你在活动期间把指定代币或稳定币锁定到资金池中，按你在池子里所占的份额每天领取即将上线的新代币。","body":[["Binance Launchpool是最知名的例子，其他",["交易所","centralized-exchange"],"也有类似活动，名字各不相同。一般流程是：交易所公布新项目和",["挖矿","mining"],"池，支持",["质押","staking"],"的资产通常是平台币或",["稳定币","stablecoin"],"；你在活动期内存入资产，奖励按小时或按天根据你的份额发放，活动结束后可以随时取回本金。"],["它的吸引力在于本金一般不会因活动本身减少，等于用持有资产的时间换取新币。但收益并不固定：池子里的总质押量越大，你的份额越小；",["新币上线","token-listing"],"后的价格也可能大幅波动，奖励的价值有时远低于预期。"],["另外要考虑机会成本和本金本身的价格风险。如果为了参与而买入平台币，平台币在活动期间下跌，损失可能超过挖到的新币价值。各平台的参与条件、是否需要KYC、是否",["限制地区","geo-restrictions"],"都不同，以活动公告为准。"]],"example":"假设某新币的Launchpool稳定币池每天发放1,000,000枚代币，池子总质押量为50,000,000 USDT。你存入1,000 USDT，份额是1,000 ÷ 50,000,000 = 0.002%，每天能领约20枚新币。活动持续10天，你共领到约200枚。如果新币上线后价格为0.05 USDT，这200枚约值10 USDT；若后来更多人加入、池子涨到100,000,000 USDT，你的每日奖励会减半到约10枚。","mistakes":["只看活动总奖励，不算池子总质押量会稀释你的份额。","为了参与活动追高买入平台币，结果平台币下跌的损失超过挖矿收益。","以为挖到的新币一定能以高价卖出，忽视上线后的价格波动。"],"faq":[{"q":"Launchpool会亏本金吗？","a":"活动本身通常不扣本金，但你质押的资产价格可能下跌，新币奖励的价值也可能很低，所以整体仍可能亏损。"},{"q":"Launchpool和Launchpad有什么区别？","a":"Launchpool是锁仓挖矿免费领新币，Launchpad是用资金认购新币份额，后者需要真正花钱购买。"}],"title":"什么是Launchpool？交易所质押挖新币怎么算","description":"Launchpool是什么？了解交易所质押挖新币的流程、每日奖励按份额怎么计算、池子规模如何稀释收益，以及平台币价格的风险。","related":[["launchpad","Launchpad（新币首发认购）","Launchpad是交易所或链上平台为新项目举办的代币首发认购活动，用户在上线交易前用稳定币或平台币按固定价格认购新币，超额认购时按比例分配。"],["staking","质押（Staking）","质押是把权益证明（PoS）区块链的代币锁定，用来支持网络验证并获得奖励的做法，你可以自己运行验证节点，也可以通过交易所或质押服务参与。"],["airdrop","空投（Airdrop）","空投是项目方免费向符合条件的钱包地址或用户发放代币的方式，常用于奖励早期用户、分散持币和推广项目。"],["token-listing","上币（Token listing）","上币是指交易所正式开放某个代币的充值和交易，为它开设现货或合约交易对，让用户可以在平台上买卖，通常会提前发布上币公告和开盘时间。"]],"lesson":null,"coin":null,"tool":"/activities","cta":true}});
